import*as TimelineModel from"../../models/timeline_model/timeline_model.js";import{TimelineUIUtils}from"./TimelineUIUtils.js";export class IsLong extends TimelineModel.TimelineModelFilter.TimelineModelFilter{minimumRecordDuration;constructor(){super(),this.minimumRecordDuration=0}setMinimumRecordDuration(e){this.minimumRecordDuration=e}accept(e){return(e.endTime?e.endTime-e.startTime:0)>=this.minimumRecordDuration}}export class Category extends TimelineModel.TimelineModelFilter.TimelineModelFilter{constructor(){super()}accept(e){return!TimelineUIUtils.eventStyle(e).category.hidden}}export class TimelineRegExp extends TimelineModel.TimelineModelFilter.TimelineModelFilter{regExpInternal;constructor(e){super(),this.setRegExp(e||null)}setRegExp(e){this.regExpInternal=e}regExp(){return this.regExpInternal}accept(e){return!this.regExpInternal||TimelineUIUtils.testContentMatching(e,this.regExpInternal)}}